class Base {
public:
    // Base VTable Slot 0: &Base::func_a
    virtual void func_a() const;
    // Base VTable Slot 1: &Base::func_b
    virtual void func_b() const;
};

class Derived : public Base {
public:
    // Derived VTable Slot 0: &Derived::func_a (override)
    void func_a() const override;
    // Slot 1: Inherits Base::func_b
};

// Vptr Access & Dynamic Dispatch
Base* p = new Derived();
// Runtime: p->vptr -> VTable[0] -> Derived::func_a
p->func_a();
delete p;
// Note: Object layout usually starts with the hidden vptr.
